"""CARLA recipes are dataset scenarios. Their frame data is generated by experiment preparation."""

from __future__ import annotations

import math
from collections.abc import Mapping
from copy import deepcopy
from dataclasses import dataclass, field, replace
from functools import lru_cache
from pathlib import Path
from typing import Any, TYPE_CHECKING

from avsectester.data_types import Control

from avsectester.data_types import ActorState, Unavailable
from avsectester.datasets.base import Dataset, FrameReference, ScenarioDescriptor, ScenarioStart
from avsectester.validation import require_nonnegative_integer

if TYPE_CHECKING:
    from avsectester.maps import ScenarioMap


# A curated set of built-in ``carla.WeatherParameters`` presets for world-level robustness sweeps
# (pass one as the scenario ``weather`` key). Validation accepts the full native preset set
# below; this curated sequence gives robustness sweeps a smaller clear-to-adverse spread.
CARLA_WEATHER_PRESETS = (
    "ClearNoon", "CloudyNoon", "WetNoon", "WetCloudyNoon", "MidRainyNoon", "HardRainNoon",
    "ClearSunset", "CloudySunset", "WetSunset", "HardRainSunset",
)


# Native enum names can be validated without importing the CARLA SDK or opening a world.
_MAP_LAYERS = frozenset({"Buildings", "Decals", "Foliage", "Ground", "ParkedVehicles",
                         "Particles", "Props", "StreetLights", "Walls"})
_LIGHT_GROUPS = frozenset({"Street", "Building", "Other", "None"})
_VEHICLE_LIGHTS = frozenset({"NONE", "Position", "LowBeam", "HighBeam", "Brake", "RightBlinker",
                             "LeftBlinker", "Reverse", "Fog", "Interior", "Special1", "Special2", "All"})
_WEATHER_PRESETS = frozenset({
    *CARLA_WEATHER_PRESETS, "SoftRainNoon", "WetCloudySunset", "MidRainSunset", "SoftRainSunset",
    "ClearNight", "CloudyNight", "WetNight", "WetCloudyNight", "SoftRainNight", "MidRainyNight",
    "HardRainNight", "DustStorm",
})
_WEATHER_RANGES: dict[str, tuple[float, float]] = {
    **{name: (0.0, 100.0) for name in (
        "cloudiness", "precipitation", "precipitation_deposits", "wind_intensity", "fog_density",
        "wetness", "dust_storm",
    )},
    "sun_azimuth_angle": (0.0, 360.0), "sun_altitude_angle": (-90.0, 90.0),
    **{name: (0.0, math.inf) for name in (
        "fog_distance", "fog_falloff", "scattering_intensity", "mie_scattering_scale",
        "rayleigh_scattering_scale",
    )},
}


def _settings_mapping(value: Any, allowed: set[str] | frozenset[str], name: str) -> Mapping[str, Any]:
    """Check a native-setting structure before any world operations."""
    if not isinstance(value, Mapping) or set(value) - allowed:
        raise ValueError(f"{name} supports only {', '.join(sorted(allowed))}")
    return value


def _name_list(value: Any, allowed: frozenset[str] | None, name: str) -> None:
    """Validate enum/actor names without needing native enum objects or spawned actors."""
    if (not isinstance(value, (list, tuple))
            or any(not isinstance(item, str) or not item for item in value)
            or (allowed is not None and any(item not in allowed for item in value))):
        raise ValueError(f"{name} requires supported nonempty names")


def _finite_number(value: Any, name: str, low: float, high: float = math.inf) -> None:
    """Reject booleans, coercible strings, NaNs and values outside the native range."""
    if (isinstance(value, bool) or not isinstance(value, (int, float))
            or not math.isfinite(value) or not low <= value <= high):
        raise ValueError(f"{name} must be a finite number in [{low}, {high}]")


def _validate_map_layers(settings: Any) -> None:
    if settings is None:
        return
    settings = _settings_mapping(settings, {"load", "unload"}, "map_layers")
    for action in ("unload", "load"):
        _name_list(settings.get(action, []), _MAP_LAYERS, f"map_layers.{action}")


def _validate_lighting(settings: Any) -> None:
    if settings is None:
        return
    settings = _settings_mapping(settings, {"street_lights", "vehicle_lights"}, "lighting")
    scene = settings.get("street_lights")
    if scene is not None:
        scene = _settings_mapping(scene, {"enabled", "intensity", "color", "group"}, "street_lights")
        group = scene.get("group", "Street")
        if not isinstance(group, str) or group not in _LIGHT_GROUPS:
            raise ValueError("street_lights.group must be Street, Building, Other or None")
        if "enabled" in scene and not isinstance(scene["enabled"], bool):
            raise ValueError("street_lights.enabled must be a boolean")
        if "intensity" in scene:
            _finite_number(scene["intensity"], "street_lights.intensity", 0)
        if "color" in scene:
            color = scene["color"]
            if (not isinstance(color, (list, tuple)) or len(color) != 3
                    or any(isinstance(c, bool) or not isinstance(c, int) or not 0 <= c <= 255
                           for c in color)):
                raise ValueError("street_lights.color requires three integers in [0,255]")
    vehicles = settings.get("vehicle_lights", {})
    if not isinstance(vehicles, Mapping) or any(not isinstance(key, str) or not key for key in vehicles):
        raise ValueError("vehicle_lights maps stable actor IDs (or all) to light flag lists")
    for flags in vehicles.values():
        _name_list(flags, _VEHICLE_LIGHTS, "vehicle_lights values")


def _validate_road_friction(settings: Any) -> None:
    if settings is None:
        return
    settings = _settings_mapping(settings, {"tire_friction", "actors"}, "road_friction")
    value = settings.get("tire_friction")
    _finite_number(value, "road_friction.tire_friction", 0)
    if value == 0:
        raise ValueError("road_friction.tire_friction must be positive")
    if "actors" in settings:
        _name_list(settings["actors"], None, "road_friction.actors")


def _validate_weather(settings: Any) -> None:
    if settings is None:
        return
    if isinstance(settings, str):
        if settings not in _WEATHER_PRESETS:
            raise ValueError(f"unknown CARLA weather preset {settings!r} (see CARLA_WEATHER_PRESETS)")
        return
    settings = _settings_mapping(settings, set(_WEATHER_RANGES), "weather")
    for name, value in settings.items():
        _finite_number(value, f"weather.{name}", *_WEATHER_RANGES[name])


_CARLA_WORLD_VALIDATORS = {
    "weather": _validate_weather, "lighting": _validate_lighting,
    "map_layers": _validate_map_layers, "road_friction": _validate_road_friction,
}
CARLA_WORLD_SETTINGS = frozenset(_CARLA_WORLD_VALIDATORS)


def validate_carla_world_settings(settings: Mapping[str, Any]) -> None:
    """Validate data-only CARLA world settings without SDK imports or a live connection."""
    validators = _CARLA_WORLD_VALIDATORS
    if not isinstance(settings, Mapping):
        raise TypeError("CARLA world settings must be a mapping")
    unsupported = set(settings) - validators.keys()
    if unsupported:
        raise ValueError(f"Unsupported CARLA world settings: {sorted(unsupported)}")
    for name, value in settings.items():
        validators[name](value)


@dataclass(frozen=True)
class PrescribedMotion:
    """One control sequence, trajectory, or constant actuator control.

    A recipe expands ``constant_control`` into independent controls for every decision.
    Trajectories include N+1 states with velocity evidence and never imply a policy.
    """

    controls: tuple[Control, ...] = ()
    trajectory: tuple[ActorState, ...] = ()
    constant_control: Control | None = None

    def expanded(self, decision_steps: int) -> PrescribedMotion:
        if sum((bool(self.controls), bool(self.trajectory), self.constant_control is not None)) != 1:
            raise ValueError("Specify exactly one of controls, trajectory, constant_control")
        motion = self
        if self.constant_control is not None:
            motion = replace(
                self, controls=tuple(deepcopy(self.constant_control) for _ in range(decision_steps)),
                constant_control=None,
            )
        motion.validate(decision_steps)
        return motion

    def validate(self, decision_steps: int) -> None:
        if bool(self.controls) == bool(self.trajectory):
            raise ValueError("Specify exactly one explicit control or trajectory sequence")
        if self.controls:
            if len(self.controls) != decision_steps:
                raise ValueError("Control sequence must cover every recipe decision")
            for control in self.controls:
                if not isinstance(control, Control) or control.trajectory is not None:
                    raise ValueError("CARLA prescribed controls must be actuator commands")
                if not all(math.isfinite(value) for value in
                           (control.throttle, control.brake, control.steer)):
                    raise ValueError("Prescribed controls must be finite")
        else:
            if len(self.trajectory) != decision_steps + 1:
                raise ValueError("Trajectory must include the terminal state")
            if any(state.velocity is None for state in self.trajectory):
                raise ValueError("Prescribed trajectories require velocity evidence")


@dataclass(frozen=True)
class CarlaRecipe:
    scenario: dict
    decision_steps: int
    time_step: float
    motion: Mapping[str, PrescribedMotion]
    metadata: Mapping = field(default_factory=dict)

    def __post_init__(self) -> None:
        require_nonnegative_integer(self.decision_steps, "decision_steps")
        if self.decision_steps == 0:
            raise ValueError("A recipe must prescribe at least one decision")
        if not math.isfinite(self.time_step) or self.time_step <= 0:
            raise ValueError("time_step must be positive and finite")
        scenario = deepcopy(self.scenario)
        world_names = CARLA_WORLD_SETTINGS
        validate_carla_world_settings({name: value for name, value in scenario.items()
                                       if name in world_names})
        client = scenario.get("client", {})
        if not isinstance(client, Mapping):
            raise TypeError("Recipe scenario.client must be a mapping")
        forbidden = set(client) & {
            "connect_ip", "connect_port", "traffic_manager_port", "rate", "synchronous",
            "seed", "traffic_manager_seed",
        }
        if forbidden:
            raise ValueError(
                "Recipe client contains simulator runtime settings: " + ", ".join(sorted(forbidden))
            )
        npcs = scenario.get("npcs") or []
        if isinstance(npcs, dict):
            raise ValueError("Expand NPCs into explicit spawn/motion specifications for a recipe")
        if any(not isinstance(npc, Mapping) or not ({"spawn", "spawn_transform"} & npc.keys())
               for npc in npcs):
            raise ValueError("Recipe NPCs require explicit spawn or spawn_transform")
        actors = {"ego", *(f"npc:{i}" for i in range(len(npcs)))}
        if scenario.get("lead") is not None:
            actors.add("lead")
        if set(self.motion) != actors:
            raise ValueError(f"Explicit motion required for exactly these actors: {sorted(actors)}")
        if scenario["ego"].get("autopilot") or any(npc.get("autopilot", False) for npc in npcs):
            raise ValueError("Traffic Manager motion is unsupported for reference recipes")
        expanded = {}
        for actor_id, motion in self.motion.items():
            if not isinstance(motion, PrescribedMotion):
                raise TypeError("Recipe motion values must be PrescribedMotion")
            expanded[actor_id] = motion.expanded(self.decision_steps)
        object.__setattr__(self, "scenario", scenario)
        object.__setattr__(self, "motion", deepcopy(expanded))
        object.__setattr__(self, "metadata", deepcopy(dict(self.metadata)))


class CarlaDataset(Dataset):
    def __init__(self, recipes: Mapping[str, CarlaRecipe], map_directory: str | Path | None = None) -> None:
        self._recipes = deepcopy(dict(recipes))
        self.map_directory = Path(map_directory) if map_directory is not None else None

    def scenarios(self):
        for identity in self._recipes:
            yield ScenarioDescriptor(identity, "CarlaDataset", {"recipe_only": True})

    def frames(self, scenario_id):
        recipe = self._recipes[scenario_id]
        return tuple(FrameReference(scenario_id, i, i, i * recipe.time_step)
                     for i in range(recipe.decision_steps + 1))

    def frame_data(self, scenario_id, frame):
        self.checked_frame(scenario_id, frame)
        return Unavailable("recipe_only")

    def native(self, scenario_id):
        return deepcopy(self._recipes[scenario_id])

    @lru_cache(maxsize=8)
    def scenario_map(self, scenario_id: str) -> ScenarioMap | Unavailable:
        """Read an exported OpenDRIVE map without connecting to a CARLA server."""
        from avsectester.maps import read_opendrive

        recipe = self._recipes[scenario_id]
        map_name = recipe.scenario.get("client", {}).get("map_name")
        usage = ("Export maps with python scripts/preparation/export_carla_maps.py "
                 "--town Town03 --output <directory>, then set CarlaDataset.map_directory")
        if not map_name:
            return Unavailable(f"The CARLA recipe has no map_name. {usage}")
        if self.map_directory is None:
            return Unavailable(f"No CARLA map_directory was supplied. {usage}")
        name = str(map_name).rsplit("/", 1)[-1]
        path = self.map_directory / f"{name}.xodr"
        if not path.is_file():
            return Unavailable(f"CARLA map file not found: {path}. {usage}")
        return read_opendrive(path.read_text(encoding="utf-8"), name=name)

    def scenario_start(self, scenario_id, frame):
        self.checked_frame(scenario_id, frame)
        return ScenarioStart("CarlaDataset", scenario_id, frame, {"recipe": self.native(scenario_id)},
                             scenario_map=self.scenario_map(scenario_id))
